example.code:
IFontsFactory fontsFactory = new FontsFactory();
IRenderersFactory renderersFactory = RenderersFactory.Instance;
IImageConverterService converterService = new ImageConverterService();
var imageRendering = new ImageRendering(fontsFactory, renderersFactory, converterService);

IReport report = new Report();
Func{int, Stream} streamProvider = pageIndex => new FileStream($"page{pageIndex}.png", FileMode.Create);
var settings = new ImageRenderingSettings { OutputFormat = ImageFormats.Png };
imageRendering.Render(report, streamProvider, settings);

IReport report = new Report();
Func{int, Stream} streamProvider = pageIndex => new FileStream($"page{pageIndex}.png", FileMode.Create);
var settings = new ImageRenderingSettings { OutputFormat = ImageFormats.Png };
imageRendering.Render(report, streamProvider, settings, CancellationToken.None);

IReport report = new Report();
Func{int, Stream} streamProvider = pageIndex => new FileStream($"page{pageIndex}.png", FileMode.Create);
var settings = new ImageRenderingSettings { OutputFormat = ImageFormats.Png };
var progress = new Progress<ProgressInfo>();
imageRendering.Render(report, streamProvider, settings, CancellationToken.None, progress);
